package com.aitu.lms.observer;
import java.time.Instant; import java.util.concurrent.atomic.AtomicInteger;
public final class AggregatingListener implements Observer, Subject { private final Subject downstream; private final AtomicInteger gradeCount=new AtomicInteger(); public AggregatingListener(Subject downstream){this.downstream=downstream;} public void onEvent(Event e){gradeCount.incrementAndGet(); downstream.publish(new Event(EventType.GPA_UPDATED,e.studentId(),"Aggregated grade events="+gradeCount.get(),Instant.now()));} public void subscribe(EventType t,Observer o){downstream.subscribe(t,o);} public void unsubscribe(EventType t,Observer o){downstream.unsubscribe(t,o);} public void publish(Event e){downstream.publish(e);} public int aggregateCount(){return gradeCount.get();} }
